--
-- Dumping data for table method
--
INSERT INTO `method` (`id`, `advantages`, `description`, `disadvantages`, `name`, `methodology_id`) VALUES
(1,'- Les exigences sont bien définies et peu susceptibles de changer.\n- Les projets sont simples et de courte durée.',
    '- Le modèle en cascade est une méthode séquentielle dans laquelle les phases du projet (analyse, conception, développement, tests, déploiement) sont exécutées l''une après l''autre, sans retour possible en arrière.',
    '- Changements fréquents et projets complexes le client demande de la visibilité', 'Cascade', 1),
(2, '- Des tests à chaque phase de la conception sont envisageables.\n- Des normes élevées de qualité strictes.\n- Les projets ont des exigences claires et immuables.',
    '- Le cycle en V est une extension du modèle en cascade oû chaque phase de développement est associée à une phase de test correspondante.\nIl offre une approche plus rigide, oû la validation et la vérification sont effectuées simultanément.',
    '- Les projets nécessitent une flexibilité ou une adaptabilité à des ajustements rapides.\n- Les équipes manquent d''expertise en matière de tests rigoureux.',
    'Cycle en V', 1),
(3, '- Les projets sont complexes, de grande envergure, et comportent des risques élevés.\n- Une analyse continue des risques et des prototypes fréquents sont nécessaires.',
    '- Le modèle spirale est une méthode itérative qui combine les aspects du modèle en cascade et des méthodes agiles.\nElle met l''accent sur l''analyse des risques à chaque itération, permettant ainsi une gestion proactive des risques.',
    '- Les budgets et les délais sont très limités.\n- Les équipes manquent d''expérience en gestion des risques.\n- Le projet est de petite taille avec des exigences stables.',
    'Spirale', 1),
(4, '- Les projets nécessitent le développement parallèle de composants matériels et logiciels.\n- Une synchronisation précise entre les différents aspects du projet est essentielle.\n- Les équipes ont une expertise en gestion de projets hybrides.',
    'Le modèle en Y est une méthode hybride qui combine les éléments du cycle en V et des approches de prototypage.\nIl introduit des chemins parallèles pour le développement matériel et logiciel, tout en se rejoignant pour l''intégration et les tests.',
    '- Les projets ne comportent pas d''éléments multidisciplinaires.\n- Les ressources ne sont pas suffisantes pour gérer plusieurs chemins de développement en parallèle.',
    'Cycle en Y', 1),
(5, '- Les projets nécessitent un flux de travail continu sans cycles ou sprints définis.\n- L''objectif est d''améliorer l''efficacité et la gestion des priorités.\n- Les équipes veulent adopter une méthode flexible avec des changements progressifs.',
    'Kanban est une méthode agile qui se concentre sur la visualisation du flux de travail, la limitation du travail en cours, et l''amélioration continue.\nLes tâches sont gérées à l''aide d''un tableau Kanban qui montre leur progression.',
    '- Les équipes préfèrent une structure plus définie avec des rôles et des responsabilités claires.\n- Les projets nécessitent des délais fixes et des objectifs rigides.',
    'Kanban', 2),
(6, '- Les projets ont des exigences changeantes et complexes.\n- L''équipe de développement est autonome et pluridisciplinaire.\n- Le produit doit être livré par incréments fréquents avec des feedbacks réguliers du client.',
    'Scrum est une méthode agile qui utilise des sprints (cycles de développement courts de 2 à 4 semaines) pour livrer des incréments de produit.',
    '- La définition du périmètre n''est pas claire.\n- Les projets nécessitent des délais rigides et une planification prédictive.\n- L''équipe n''est pas familiarisée avec la méthodologie Scrum.\n- Les parties prenantes ne sont pas disponibles pour des retours fréquents.',
    'Scrum', 2),
(7, '- Les projets nécessitent une qualité de code élevée et des livraisons fréquentes.\n- Les exigences sont susceptibles de changer rapidement.\n- Les équipes de développement sont petites et très collaboratives.',
    'Extreme Programming (XP) est une méthode agile qui met l''accent sur les meilleures pratiques de développement logiciel comme les tests unitaires, la programmation en binôme, l''intégration continue, et la révision de code fréquente.',
    '- L''équipe manque d''expérience ou de discipline dans les pratiques d''ingénierie avancées.\n- Le projet a des exigences très rigides et peu susceptibles de changer.',
    'XP', 2),
(8, '- Les équipes veulent la structure de Scrum avec la flexibilité de Kanban.\n- Les projets nécessitent des livraisons continues tout en maintenant la gestion des priorités.\n- L''objectif est d''améliorer progressivement les processus tout en conservant certaines pratiques de Scrum.',
    'Scrumban combine les pratiques de Scrum et de Kanban.\nIl conserve la structure de Scrum (rôles, sprints, rétrospectives) tout en adoptant la flexibilité de Kanban (flux de travail continu, gestion du travail en cours).',
    '- Les équipes préfèrent une approche purement Scrum ou Kanban.\n- Les projets nécessitent une approche rigide et très structurée.',
    'Scrumban', 2),
(9, '- L''organisation cherche à optimiser ses processus et réduire les gaspillages.\n- Les projets nécessitent des cycles de livraison courts avec une focalisation sur la valeur.',
    'Lean est une approche de gestion de projet visant à maximiser la valeur tout en minimisant le gaspillage.\nIl se concentre sur l''efficacité, l''amélioration continue, et la livraison rapide de valeur au client.',
    '- Les équipes ont besoin de directives et de structures rigides.\n- L''organisation n''a pas de culture d''amélioration continue.\n- Les processus actuels sont déjà très optimisés.',
    'Lean', 2),
(10, '- L''organisation veut une approche hybride qui combine plusieurs pratiques.\n- Les équipes ont besoin de lignes directrices pour des pratiques d''agilité d''entreprise.\n- Le projet est de grande envergure et nécessite une approche adaptable.',
     'Disciplined Agile Delivery (DAD) est un cadre de gestion de projet agile qui fournit des lignes directrices pour des équipes qui évoluent, combinant des pratiques d''Agile, Lean, et autres approches.\nIl couvre toutes les étapes de développement, de l''initialisation au déploiement.',
     '- Les projets sont petits et ne nécessitent pas de pratiques agiles d''entreprise.\n- Les équipes préfèrent des cadres plus simples comme Scrum ou Kanban.\n- L''organisation a des contraintes rigides et préfère une approche unique.',
     'Dad', 2),
(11, '- L''organisation a plusieurs équipes de développement nécessitant une synchronisation.\n- Les projets sont de grande envergure, avec des dépendances complexes.\n- L''entreprise souhaite aligner l''agilité de l''équipe avec des objectifs d''entreprise plus larges.',
     'Scaled Agile Framework (SAFe) est un cadre qui permet de mettre à l''échelle les pratiques agiles pour de grandes entreprises.\nIl fournit une structure pour aligner le développement à grande échelle avec les objectifs stratégiques de l''entreprise.',
     '- Les équipes ou les projets sont petits et ne nécessitent pas de mise à l''échelle.\n- L''organisation préfère des approches moins formelles.',
     'Safe', 2),
(12, '- L''organisation utilise déjà Scrum et souhaite l''étendre à plusieurs équipes.\n- Le projet est complexe et nécessite une collaboration inter-équipes.\n- L''entreprise souhaite minimiser la bureaucratie tout en mettant à l''échelle.',
     'Large-Scale Scrum (LeSS) est une extension de Scrum pour les grandes équipes de développement.\nIl conserve les principes de base de Scrum tout en les adaptant à une échelle plus grande, avec plusieurs équipes travaillant sur le même produit.',
     '- Les équipes n''ont pas d''expérience avec Scrum.\n- L''organisation a des exigences rigides de processus et de documentation.\n- Les projets ne sont pas assez grands pour justifier la mise à l''échelle.',
     'Less', 2),
(13, '- Les équipes Scrum doivent collaborer sur des produits complexes.\n- L''accent est mis sur l''intégration continue et la gestion des dépendances.\n- L''organisation veut utiliser un cadre qui reste proche des principes de Scrum.',
     'Nexus est un cadre de mise à l''échelle de Scrum conçu pour des équipes qui travaillent ensemble sur un produit unique.\nIl se concentre sur la gestion des dépendances et l''intégration continue.',
     '- Les équipes ne sont pas familiarisées avec Scrum.\n- Le projet est simple et n''a pas besoin de mise à l''échelle.\n- Les équipes préfèrent des approches plus légères comme LeSS.',
     'Nexus', 2),
(14, '- Plusieurs équipes Scrum doivent travailler en parallèle et coordonner leurs efforts.\n- L''objectif est de gérer les interdépendances tout en utilisant les principes Scrum.',
     'Scrum of Scrums est une technique de coordination utilisée pour mettre à l''échelle Scrum dans les grandes organisations.\nDes représentants de chaque équipe Scrum se rencontrent régulièrement pour coordonner le travail.',
     '- Les équipes ne sont pas autonomes ou ne maîtrisent pas bien Scrum.\n- Le projet est petit ou n''implique qu''une seule équipe.\n- Il n''y a pas de besoins de coordination fréquente.',
     'Scrum of Scrums', 2),
(15, '- L''organisation veut encourager une culture d''autonomie et d''innovation.\n- L''accent est mis sur la flexibilité organisationnelle et la collaboration.\n- Les équipes préfèrent travailler de manière autonome tout en maintenant une synchronisation.',
     'Le modèle Spotify est une approche de gestion d''équipe agile, mettant l''accent sur la culture et la structure d''équipe autonome.\nIl vise à maximiser l''alignement et l''autonomie.',
     '- L''organisation nécessite des contrôles stricts et une hiérarchie rigide.\n- Les équipes n''ont pas l''expérience nécessaire pour gérer leur autonomie.\n- Les projets ont des exigences formelles de documentation et de processus.',
     'Spotify', 2),
(16, '- L''organisation veut appliquer des principes agiles au niveau de l''entreprise, pas seulement au développement.\n- Les équipes veulent un cadre flexible mais structuré pour différents départements.\n- L''objectif est d''aligner l''ensemble de l''organisation avec une culture agile.',
     'Enterprise Scrum est une méthode d''échelle agile qui permet l''application de Scrum dans divers contextes organisationnels (marketing, vente, etc., pas seulement pour le développement logiciel.',
     '- L''entreprise n''a pas de culture d''innovation ou de flexibilité.\n- Les équipes ne maîtrisent pas les concepts de base de Scrum.\n- Les projets sont déjà bien gérés avec d''autres cadres d''agilité à l''échelle.',
     'Enterprise Scrum (ES)', 2);
